#[test]
fn handles_empty_quoted_values() {
    let content = "DOUBLE=\"\"\nSINGLE=''";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("DOUBLE"), Some(&"".to_string()));
    assert_eq!(vars.get("SINGLE"), Some(&"".to_string()));
}

#[test]
fn mismatched_quotes_are_kept_literal() {
    let content = "A=\"value'\nB='value\"";

    let vars = EnvFileParser::parse(content).unwrap();

    // Mismatched quotes should not be stripped
    assert_eq!(vars.get("A"), Some(&"\"value'".to_string()));
    assert_eq!(vars.get("B"), Some(&"'value\"".to_string()));
}

#[test]
fn single_quote_character_as_value() {
    let content = "Q='";

    let vars = EnvFileParser::parse(content).unwrap();

    // A lone quote is not a matching pair, kept as-is
    assert_eq!(vars.get("Q"), Some(&"'".to_string()));
}

#[test]
fn single_double_quote_character_as_value() {
    let content = "Q=\"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("Q"), Some(&"\"".to_string()));
}

#[test]
fn quotes_embedded_inside_other_quotes() {
    let content = "A=\"it's a test\"\nB='say \"hello\"'";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("A"), Some(&"it's a test".to_string()));
    assert_eq!(vars.get("B"), Some(&"say \"hello\"".to_string()));
}

#[test]
fn escaped_double_quotes_inside_double_quotes_not_processed() {
    // The parser does NOT handle escape sequences — backslashes are literal
    let content = r#"KEY="value with \"escaped\" quotes""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // The outer quotes are stripped, but \" remains literal because the
    // parser doesn't process escapes. The value starts with " and ends with "
    // so unquote strips the first and last character.
    // Full value after = is: "value with \"escaped\" quotes"
    // starts_with(") and ends_with(") → strip outer quotes
    // Result: value with \"escaped\" quotes
    assert_eq!(
        vars.get("KEY"),
        Some(&r#"value with \"escaped\" quotes"#.to_string())
    );
}

#[test]
fn backslash_sequences_are_literal() {
    // \n, \t, \\ are NOT interpreted — they stay as-is
    let content = "A=hello\\nworld\nB=\"tab\\there\"\nC='back\\\\slash'";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("A"), Some(&"hello\\nworld".to_string()));
    assert_eq!(vars.get("B"), Some(&"tab\\there".to_string()));
    assert_eq!(vars.get("C"), Some(&"back\\\\slash".to_string()));
}

#[test]
fn value_with_only_whitespace() {
    let content = "KEY=   ";

    let vars = EnvFileParser::parse(content).unwrap();

    // Value is trimmed
    assert_eq!(vars.get("KEY"), Some(&"".to_string()));
}

#[test]
fn quoted_value_preserves_inner_whitespace() {
    let content = "KEY=\"  spaced  \"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
}

#[test]
fn inline_comment_is_not_stripped() {
    // The parser does NOT strip inline comments — the # is part of the value
    let content = "KEY=value # not a comment";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(
        vars.get("KEY"),
        Some(&"value # not a comment".to_string())
    );
}

#[test]
fn hash_in_quoted_value() {
    let content = "KEY=\"value#with#hashes\"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(
        vars.get("KEY"),
        Some(&"value#with#hashes".to_string())
    );
}

#[test]
fn export_prefix_becomes_part_of_key() {
    // The parser does NOT handle the `export` keyword
    let content = "export KEY=value";

    let vars = EnvFileParser::parse(content).unwrap();

    // "export KEY" is treated as the key
    assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
    assert_eq!(vars.get("KEY"), None);
}

